// Centerline Labeling — Text, route: jsx
// Source: centerline-labeling
//
// Self-contained: every local import is inlined below. Requires only d3, geojson, react, topojson-client, topojson-specification, us-atlas, world-atlas.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { feature, mesh } from 'topojson-client';
import countries110m from 'world-atlas/countries-110m.json';
import statesUs from 'us-atlas/states-10m.json';
import type { GeometryCollection, Topology } from 'topojson-specification';
import type { Feature, FeatureCollection, Geometry, MultiLineString } from 'geojson';
import * as d3 from 'd3';
import { useId, useMemo } from 'react';

// ---- inlined from geo ----
// The atlases ship untyped JSON. One cast per topology at this boundary keeps every
// consumer strict, and converting here means each chart does not re-derive the same
// geometry at module load.

type Named = { name: string };
type NamedFeature = Feature<Geometry, Named>;

const world = countries110m as unknown as Topology<{
  countries: GeometryCollection<Named>;
  land: GeometryCollection;
}>;

const us = statesUs as unknown as Topology<{
  states: GeometryCollection<Named>;
  nation: GeometryCollection;
}>;

const worldCountries = feature(
  world,
  world.objects.countries
) as FeatureCollection<Geometry, Named>;

const worldLand = feature(world, world.objects.land) as FeatureCollection<Geometry>;

/** Shared borders only, so neighbouring outlines are stroked once instead of twice. */
const worldBorders = mesh(
  world,
  world.objects.countries,
  (a, b) => a !== b
) as MultiLineString;

const usNation = feature(us, us.objects.nation) as FeatureCollection<Geometry>;

const usStateBorders = mesh(
  us,
  us.objects.states,
  (a, b) => a !== b
) as MultiLineString;

/**
 * The 50 states plus DC. geoAlbersUsa cannot project FIPS ids of 60 and above
 * (territories) and returns null for them, which becomes a NaN centroid downstream.
 * Use this rather than the raw collection for anything Albers-projected.
 */
const usStates: NamedFeature[] = (
  feature(us, us.objects.states) as FeatureCollection<Geometry, Named>
).features.filter((d) => Number(d.id) < 60);

const usStatesCollection: FeatureCollection<Geometry, Named> = {
  type: 'FeatureCollection',
  features: usStates
};

/**
 * FNV-1a over an id, run through the murmur3 finalizer. Two-character FIPS ids barely
 * differ, and without the finalizer they map to a near-constant. Returns [0, 1).
 * Charts use it to synthesize per-region values deterministically instead of fetching.
 */
function hashUnit(id: string, salt = 0): number {
  let h = 2166136261 ^ salt;
  for (let i = 0; i < id.length; i++) {
    h = Math.imul(h ^ id.charCodeAt(i), 16777619);
  }
  h ^= h >>> 16;
  h = Math.imul(h, 2246822507);
  h ^= h >>> 13;
  return (h >>> 0) / 4294967296;
}

// ---- inlined from centerline ----
type Point = [number, number];

const dist = (a: Point, b: Point) => Math.hypot(a[0] - b[0], a[1] - b[1]);

/** Wide, awkwardly shaped states: the case a horizontal label handles worst. */
const NAMES = ['Tennessee', 'Kentucky', 'Oklahoma', 'Florida'];

const regions: NamedFeature[] = NAMES.map((name) =>
  usStates.find((d) => d.properties.name === name)
).filter((d): d is NamedFeature => d !== undefined);

/** The state's largest ring in screen space; islands and exclaves carry no label. */
function largestRing(feature: NamedFeature, projection: d3.GeoProjection): Point[] {
  const { geometry } = feature;
  const polygons =
    geometry.type === 'MultiPolygon'
      ? geometry.coordinates
      : geometry.type === 'Polygon'
        ? [geometry.coordinates]
        : [];

  let best: Point[] = [];
  for (const polygon of polygons) {
    const ring = polygon[0]
      .map((c) => projection([c[0], c[1]]))
      .filter((p): p is [number, number] => p !== null);
    if (Math.abs(d3.polygonArea(ring)) > Math.abs(d3.polygonArea(best))) best = ring;
  }
  return best;
}

function projectRegion(feature: NamedFeature, width: number, height: number) {
  const projection = d3
    .geoAlbersUsa()
    .fitExtent(
      [
        [6, 6],
        [Math.max(7, width - 6), Math.max(7, height - 6)]
      ],
      feature
    );
  return { outline: d3.geoPath(projection)(feature) ?? '', ring: largestRing(feature, projection) };
}

function resample(ring: Point[], count: number): Point[] {
  const closed = [...ring, ring[0]];
  const cumulative = [0];
  for (let i = 1; i < closed.length; i++) {
    cumulative.push(cumulative[i - 1] + dist(closed[i - 1], closed[i]));
  }
  const total = cumulative[cumulative.length - 1];
  const out: Point[] = [];
  let seg = 1;
  for (let i = 0; i < count; i++) {
    const target = (i / count) * total;
    while (seg < cumulative.length - 1 && cumulative[seg] < target) seg++;
    const span = cumulative[seg] - cumulative[seg - 1] || 1;
    const t = (target - cumulative[seg - 1]) / span;
    out.push([
      closed[seg - 1][0] + t * (closed[seg][0] - closed[seg - 1][0]),
      closed[seg - 1][1] + t * (closed[seg][1] - closed[seg - 1][1])
    ]);
  }
  return out;
}

type Adjacency = Map<number, { to: number; weight: number }[]>;

/** Interior Voronoi edges of evenly spaced boundary samples: the medial axis of the shape. */
function medialAxis(polygon: Point[], sampleCount: number) {
  const ring = resample(polygon, sampleCount);
  const delaunay = d3.Delaunay.from(ring);
  const xs = ring.map((p) => p[0]);
  const ys = ring.map((p) => p[1]);
  const { circumcenters } = delaunay.voronoi([
    Math.min(...xs) - 1,
    Math.min(...ys) - 1,
    Math.max(...xs) + 1,
    Math.max(...ys) + 1
  ]);
  const at = (t: number): Point => [circumcenters[t * 2], circumcenters[t * 2 + 1]];

  const cache = new Map<number, boolean>();
  const isInside = (t: number) => {
    let hit = cache.get(t);
    if (hit === undefined) {
      hit = d3.polygonContains(ring, at(t));
      cache.set(t, hit);
    }
    return hit;
  };

  const adjacency: Adjacency = new Map();
  const link = (a: number, b: number, weight: number) => {
    const list = adjacency.get(a);
    if (list) list.push({ to: b, weight });
    else adjacency.set(a, [{ to: b, weight }]);
  };

  const { halfedges } = delaunay;
  for (let i = 0; i < halfedges.length; i++) {
    const j = halfedges[i];
    if (j < i) continue; // dedupes each edge, and j === -1 drops the unbounded hull rays
    const ta = Math.floor(i / 3);
    const tb = Math.floor(j / 3);
    if (!isInside(ta) || !isInside(tb)) continue;
    const pa = at(ta);
    const pb = at(tb);
    if (!d3.polygonContains(ring, [(pa[0] + pb[0]) / 2, (pa[1] + pb[1]) / 2])) continue;
    const weight = dist(pa, pb);
    link(ta, tb, weight);
    link(tb, ta, weight);
  }

  return { adjacency, at, ring };
}

/**
 * Room for the label at a point on the axis. The Delaunay circumradius approximates this
 * for free, but it measures to the nearest boundary SAMPLE rather than the boundary, and
 * overshoots by enough between samples to push glyphs outside the shape.
 */
function clearanceAt(p: Point, ring: Point[]) {
  let best = Infinity;
  for (let i = 0; i < ring.length; i++) {
    best = Math.min(best, segmentDistance(p, ring[i], ring[(i + 1) % ring.length]));
  }
  return best;
}

function dijkstra(adjacency: Adjacency, source: number) {
  const distanceTo = new Map<number, number>([[source, 0]]);
  const previous = new Map<number, number>();
  const settled = new Set<number>();
  for (;;) {
    let node = -1;
    let best = Infinity;
    for (const [n, d] of distanceTo) if (!settled.has(n) && d < best) [best, node] = [d, n];
    if (node < 0) break;
    settled.add(node);
    for (const { to, weight } of adjacency.get(node) ?? []) {
      if (best + weight < (distanceTo.get(to) ?? Infinity)) {
        distanceTo.set(to, best + weight);
        previous.set(to, node);
      }
    }
  }
  return { distanceTo, previous };
}

function segmentDistance(p: Point, a: Point, b: Point) {
  const dx = b[0] - a[0];
  const dy = b[1] - a[1];
  const squared = dx * dx + dy * dy;
  const t = squared
    ? Math.max(0, Math.min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / squared))
    : 0;
  return Math.hypot(p[0] - (a[0] + t * dx), p[1] - (a[1] + t * dy));
}

function simplify(points: Point[], tolerance: number): Point[] {
  if (points.length < 3) return points;
  const a = points[0];
  const b = points[points.length - 1];
  let index = 0;
  let far = -1;
  for (let i = 1; i < points.length - 1; i++) {
    const d = segmentDistance(points[i], a, b);
    if (d > far) [far, index] = [d, i];
  }
  if (far <= tolerance) return [a, b];
  return [
    ...simplify(points.slice(0, index + 1), tolerance),
    ...simplify(points.slice(index), tolerance).slice(1)
  ];
}

/** Room either side of the label's midpoint, nearest first: {offset along, half-thickness}. */
type Centerline = { d: string; profile: { offset: number; clearance: number }[] };

const curve = d3.line<Point>().curve(d3.curveCatmullRom.alpha(0.5));

/**
 * The notebook's fitness: longest path through the axis, divided by the square of its
 * sinuosity, so a long meander loses to a slightly shorter path that reads straight.
 */
function centerlineOf(polygon: Point[], sampleCount = 96): Centerline | null {
  const { adjacency, at, ring } = medialAxis(polygon, sampleCount);
  const tips = [...adjacency].filter(([, links]) => links.length === 1).map(([node]) => node);
  if (tips.length < 2) return null;

  let bestFitness = -1;
  let ids: number[] = [];
  for (let i = 0; i < tips.length; i++) {
    const { distanceTo, previous } = dijkstra(adjacency, tips[i]);
    for (const end of tips.slice(i + 1)) {
      const cost = distanceTo.get(end);
      if (!cost) continue;
      const fitness = dist(at(tips[i]), at(end)) ** 2 / cost; // === cost / sinuosity²
      if (fitness <= bestFitness) continue;
      bestFitness = fitness;
      ids = [];
      for (let n: number | undefined = end; n !== undefined; n = previous.get(n)) ids.push(n);
    }
  }
  if (ids.length < 4) return null;

  const along = ids.map(() => 0);
  for (let i = 1; i < ids.length; i++) along[i] = along[i - 1] + dist(at(ids[i - 1]), at(ids[i]));
  const total = along[ids.length - 1];

  // Trim the tips, where the axis runs into the outline and there is no room for text.
  const inner = ids.filter((_, i) => along[i] >= total * 0.05 && along[i] <= total * 0.95);
  const points = simplify((inner.length >= 4 ? inner : ids).map(at), 1.5);
  if (points[points.length - 1][0] < points[0][0]) points.reverse();

  return { d: curve(points) ?? '', profile: measure(points, ring) };
}

/**
 * Clearance sampled along the label's own path, not the raw axis nodes: simplifying and
 * smoothing move the path far enough that a profile measured before either step lets
 * glyphs run outside the shape.
 */
function measure(points: Point[], ring: Point[]) {
  const along = points.map(() => 0);
  for (let i = 1; i < points.length; i++) along[i] = along[i - 1] + dist(points[i - 1], points[i]);
  const total = along[points.length - 1];
  const profile: { offset: number; clearance: number }[] = [];

  for (let step = 0; step <= 100; step++) {
    const target = (step / 100) * total;
    let i = 1;
    while (i < points.length - 1 && along[i] < target) i++;
    const t = (target - along[i - 1]) / (along[i] - along[i - 1] || 1);
    const p: Point = [
      points[i - 1][0] + t * (points[i][0] - points[i - 1][0]),
      points[i - 1][1] + t * (points[i][1] - points[i - 1][1])
    ];
    profile.push({ offset: Math.abs(target - total / 2), clearance: clearanceAt(p, ring) });
  }
  return profile.sort((a, b) => a.offset - b.offset);
}

// Half the font size understates how far a glyph reaches: its ink box is taller than its
// em box, and on a curved path the outer edge splays further still.
const SLACK = 0.85;

/**
 * Walk out from the label's midpoint, tracking the tightest clearance seen so far; the
 * label can be as wide as twice whichever runs out first, the path or the room around it.
 */
function fitFontSize(line: Centerline, aspectRatio: number): number {
  let ceiling = Infinity;
  let maxWidth = 0;
  for (const { offset, clearance } of line.profile) {
    ceiling = Math.min(ceiling, clearance);
    maxWidth = Math.max(maxWidth, 2 * Math.min(offset, ceiling * SLACK * aspectRatio));
  }
  return maxWidth / aspectRatio;
}

const MARGIN = { top: 8, right: 8, bottom: 26, left: 8 };
const COLUMNS = 2;
const MIN_FONT_SIZE = 8;
const TRACKING = 0.06;
// Average advance per em for uppercase in the gallery's sans stack, plus the tracking below.
const GLYPH_WIDTH = 0.66 + TRACKING;

export default function CenterlineLabeling({ width }: { width: number }) {
  const height = Math.round(width * 0.62);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;
  const cellWidth = innerWidth / COLUMNS;
  const cellHeight = innerHeight / Math.ceil(regions.length / COLUMNS);
  const uid = useId().replace(/:/g, '');

  const cells = useMemo(
    () =>
      regions.map((region, i) => {
        const label = region.properties.name.toUpperCase();
        const { outline, ring } = projectRegion(region, cellWidth, cellHeight);
        const line = ring.length > 3 ? centerlineOf(ring) : null;
        const fontSize = line ? fitFontSize(line, label.length * GLYPH_WIDTH) : 0;
        return {
          label,
          outline,
          centerline: line?.d ?? '',
          fontSize: fontSize >= MIN_FONT_SIZE ? fontSize : 0,
          x: (i % COLUMNS) * cellWidth,
          y: Math.floor(i / COLUMNS) * cellHeight
        };
      }),
    [cellWidth, cellHeight]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Four US states, each labelled along a centerline computed from its own outline: the outline is sampled at even spacing, the interior edges of the samples' Voronoi diagram approximate the medial axis, the straightest long path through that axis is simplified, and the name is set on it with a textPath sized to the room the shape leaves."
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        {cells.map((cell, i) => (
          <g key={cell.label} transform={`translate(${cell.x},${cell.y})`}>
            {cell.centerline && (
              <defs>
                <path id={`${uid}-${i}`} d={cell.centerline} />
              </defs>
            )}
            <path
              d={cell.outline}
              fill="var(--accent)"
              fillOpacity={0.16}
              stroke="var(--accent)"
              strokeOpacity={0.6}
            />
            {cell.centerline && (
              <use
                href={`#${uid}-${i}`}
                fill="none"
                stroke="var(--muted)"
                strokeOpacity={0.5}
                strokeDasharray="3 4"
              />
            )}
            {cell.fontSize > 0 && (
              <text
                fontSize={cell.fontSize}
                fill="var(--text)"
                letterSpacing={`${TRACKING}em`}
                dominantBaseline="middle"
              >
                <textPath href={`#${uid}-${i}`} startOffset="50%" textAnchor="middle">
                  {cell.label}
                </textPath>
              </text>
            )}
          </g>
        ))}
      </g>
      {width >= 520 && (
        <text x={MARGIN.left} y={height - 8} fill="var(--muted)" fontSize={11}>
          Dashed line: the medial axis recovered from each outline, used as the label&rsquo;s
          textPath.
        </text>
      )}
    </svg>
  );
}
